#include <bits/stdc++.h>
using namespace std;

int main() {
    int t;
    cin >> t;
    auto f = [&](){
        long long n; cin >> n;
        vector<long long> a(3 * n);
        for(long long &x : a) cin >> x;
        sort(a.rbegin(), a.rend());
        auto A = [](pair<long long, int> x, pair<long long, int> y){
            return x.first != y.first ? (x.first > y.first ? x : y) : (x.second > y.second ? x : y);
        };
        long long l = -2e15, r = 2e15, z = 0;
        while(l <= r){
            long long C = l + (r - l) / 2;
            vector<pair<long long, int>> v(3 * n + 1, {-4e18, 0});
            v[0] = {0, 0};
            pair<long long, int> s = {0, 0};
            for(int i = 1; i <= 3 * n; i++){
                v[i] = A(v[i], {(v[i - 1].first + 6 * a[i - 1]) - C, v[i - 1].second + 1});
                if(i >= 2) v[i] = A(v[i], {v[i - 2].first + 4 * (a[i - 1] + a[i - 2]) - C, v[i - 2].second + 1});
                if(i >= 3) v[i] = A(v[i], {v[i - 3].first + 3 * (a[i - 1] + a[i - 2] + a[i - 3]) - C, v[i - 3].second + 1});
                s = A(s, v[i]);
            }
            s.second >= n ? (z = s.first + C * n, l = C + 1) : (r = C - 1);
        }
        cout << z << endl;
    };
    while(t--) f();
    return 0;
}
